#include "Runtime/HelpyOverlayOpenGL.h"
#include <cstdio>
using namespace PS::HelpyOverlayGpu;
static void Check(bool value,const char* reason){if(!value)throw std::runtime_error(reason);}
int main(){HWND window=nullptr;HDC dc=nullptr;HGLRC context=nullptr;try{
    const auto foreground=GetForegroundWindow();window=CreateWindowW(L"STATIC",L"Private OpenGL overlay fixture",WS_OVERLAPPEDWINDOW,0,0,384,256,nullptr,nullptr,GetModuleHandleW(nullptr),nullptr);Check(window!=nullptr,"OpenGL fixture window unavailable");dc=GetDC(window);
    PIXELFORMATDESCRIPTOR format{sizeof(format),1,PFD_DRAW_TO_WINDOW|PFD_SUPPORT_OPENGL|PFD_DOUBLEBUFFER,PFD_TYPE_RGBA,32};const auto chosen=ChoosePixelFormat(dc,&format);Check(chosen&&SetPixelFormat(dc,chosen,&format),"OpenGL pixel format unavailable");context=wglCreateContext(dc);Check(context&&wglMakeCurrent(dc,context),"OpenGL context unavailable");ConsumerGL consumer;consumer.Load();const auto luid=consumer.Adapter();
    ComPtr<IDXGIFactory1> factory;Need(CreateDXGIFactory1(IID_PPV_ARGS(&factory)),"Fixture DXGI unavailable");ComPtr<IDXGIAdapter1> adapter;for(UINT i=0;SUCCEEDED(factory->EnumAdapters1(i,&adapter));++i){DXGI_ADAPTER_DESC1 desc{};adapter->GetDesc1(&desc);if(desc.AdapterLuid.LowPart==luid.LowPart&&desc.AdapterLuid.HighPart==luid.HighPart)break;adapter.Reset();}Check(adapter!=nullptr,"Cannot match OpenGL GPU to producer");
    ComPtr<ID3D11Device> device;ComPtr<ID3D11DeviceContext> graphics;Need(D3D11CreateDevice(adapter.Get(),D3D_DRIVER_TYPE_UNKNOWN,nullptr,D3D11_CREATE_DEVICE_BGRA_SUPPORT,nullptr,0,D3D11_SDK_VERSION,&device,nullptr,&graphics),"OpenGL producer GPU unavailable");
    char nonce[33]{};std::snprintf(nonce,sizeof(nonce),"%032llx",static_cast<unsigned long long>(GetTickCount64())*GetCurrentProcessId());Producer producer;producer.Create(device.Get(),GetCurrentProcessId(),nonce,256,128);producer.Page->Left=16;producer.Page->Top=16;producer.Page->Opacity=10000;const auto slot=producer.Begin();const float red[]{.25f,0,0,.5f};graphics->ClearRenderTargetView(producer.Targets[slot].Get(),red);producer.Publish(slot);
    consumer.Create(GetCurrentProcessId(),nonce);Check(glGetError()==GL_NO_ERROR,"OpenGL shared import failed");RECT area{};GetClientRect(window,&area);glClearColor(0,0,1,1);glClear(GL_COLOR_BUFFER_BIT);glViewport(3,7,100,90);glEnable(GL_SCISSOR_TEST);producer.Page->Visible=1;producer.Page->Heartbeat=GetTickCount64();Check(consumer.Draw(area.right,area.bottom),"OpenGL overlay did not draw");Check(glGetError()==GL_NO_ERROR,"OpenGL draw raised an error");GLint viewport[4]{};glGetIntegerv(GL_VIEWPORT,viewport);Check(viewport[0]==3&&viewport[1]==7&&glIsEnabled(GL_SCISSOR_TEST),"OpenGL game state was changed");
    GLubyte inside[4]{},outside[4]{};glReadBuffer(GL_BACK);glReadPixels(26,area.bottom-27,1,1,GL_RGBA,GL_UNSIGNED_BYTE,inside);glReadPixels(0,0,1,1,GL_RGBA,GL_UNSIGNED_BYTE,outside);Check(inside[0]>=62&&inside[0]<=66&&inside[2]>=126&&inside[2]<=130,"OpenGL composition pixels differ");Check(outside[0]==0&&outside[2]==255,"OpenGL changed pixels outside the panel");
    glFinish();Check(producer.Done->GetCompletedValue()>=1,"OpenGL completion fence was not shared");producer.Page->Visible=0;Check(!consumer.Draw(area.right,area.bottom),"Hidden OpenGL overlay draws");consumer.Reset();producer.Reset();wglMakeCurrent(nullptr,nullptr);wglDeleteContext(context);ReleaseDC(window,dc);DestroyWindow(window);Check(GetForegroundWindow()==foreground,"OpenGL overlay stole focus");std::puts("OpenGL native shared-GPU pixels, fences, render-state restoration and hidden pass-through passed.");return 0;
}catch(const std::exception& error){std::fprintf(stderr,"%s\n",error.what());if(context){wglMakeCurrent(nullptr,nullptr);wglDeleteContext(context);}if(dc&&window)ReleaseDC(window,dc);if(window)DestroyWindow(window);return 1;}}
